// Recebe o aviso do InHire, confere o segredo e decide se o candidato deve ser avisado
// ===== ADAPTADOR InHire → formato interno =====
// Único trecho que conhece o formato do InHire. Na integração real, ajuste SÓ esta função
// (ela é igual nos workflows 01, 02 e 03 — mude nos três).
function deInhire(app) {
  return {
    id: app.id,
    nome: app.talent?.name || '',
    telefone: app.talent?.phone || '',
    vaga: app.job?.name || '',
    etapa: app.stage || '',
    consentimento_whatsapp: app.customFields?.consentimento_whatsapp === true,
  };
}
// ==============================================

function payloadTemplate(telefone, template, params) {
  return {
    messaging_product: 'whatsapp',
    to: telefone,
    type: 'template',
    template: template === 'hello_world'
      // Template de teste que já vem aprovado no número de teste da Meta
      ? { name: 'hello_world', language: { code: 'en_US' } }
      : { name: template, language: { code: 'pt_BR' }, components: [{ type: 'body',
          parameters: params.map((text) => ({ type: 'text', text })) }] },
  };
}

const req = $input.first().json;
if (!$env.INHIRE_WEBHOOK_SECRET || req.headers?.['x-inhire-secret'] !== $env.INHIRE_WEBHOOK_SECRET) {
  throw new Error('Webhook do InHire recusado: X-Inhire-Secret ausente ou diferente de INHIRE_WEBHOOK_SECRET');
}

const ev = req.body || {};
if (ev.event !== 'application.stage_changed' || !ev.data?.application) return [];

const c = deInhire(ev.data.application);
if (!c.consentimento_whatsapp) return [];

// Proposta, contratação e desistência são tratadas pessoalmente pela recrutadora
const SEM_AVISO_AUTOMATICO = ['Proposta', 'Contratado', 'Desistiu'];
if (SEM_AVISO_AUTOMATICO.includes(c.etapa)) return [];

const primeiroNome = c.nome.split(' ')[0];
const payload = c.etapa === 'Reprovado'
  // encerramento_processo: {{1}} nome, {{2}} vaga
  ? payloadTemplate(c.telefone, $env.WA_TEMPLATE_CLOSE || 'hello_world', [primeiroNome, c.vaga])
  // mudanca_etapa: {{1}} nome, {{2}} vaga, {{3}} etapa
  : payloadTemplate(c.telefone, $env.WA_TEMPLATE_STAGE || 'hello_world', [primeiroNome, c.vaga, c.etapa]);

return [{ json: { id: c.id, nome: c.nome, etapaAnterior: ev.data.previousStage, etapa: c.etapa, payload } }];

// Grava a data do último contato (dado NOSSO, não do InHire) de quem recebeu com sucesso
const fs = require('fs');
const ARQ = '/files/contatos.json';
const enviados = $('Validar evento').all();
const respostas = $input.all();

const ok = new Set();
const falhas = [];
respostas.forEach((r, i) => {
  if (r.json.messages) ok.add(enviados[i].json.id);
  else falhas.push({ candidato: enviados[i].json.nome, erro: r.json.error || r.json });
});

const contatos = fs.existsSync(ARQ) ? JSON.parse(fs.readFileSync(ARQ, 'utf8')) : {};
const agora = new Date().toISOString();
ok.forEach((id) => { contatos[id] = agora; });
fs.writeFileSync(ARQ, JSON.stringify(contatos, null, 2));

return [{ json: { enviados: ok.size, falhas } }];
